package com.wanyuecity.energy.operation;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@Service public class OperationClearanceTemplateService{
 private final JdbcTemplate jdbc;private final ObjectMapper json;public OperationClearanceTemplateService(JdbcTemplate jdbc,ObjectMapper json){this.jdbc=jdbc;this.json=json;}
 public List<Map<String,Object>>list(){return jdbc.queryForList("SELECT t.id,t.name,t.business_type businessType,COALESCE(d.item_label,CASE WHEN t.business_type='DEFAULT' THEN '通用模板' ELSE t.business_type END) businessTypeLabel,t.version_no versionNo,t.fields_json fieldsJson,t.enabled,t.remark,t.created_by createdBy,t.updated_at updatedAt FROM operation_clearance_template t LEFT JOIN business_dictionary d ON d.dict_type='BUSINESS_TYPE' AND d.item_value=t.business_type ORDER BY t.business_type,t.version_no DESC");}
 public Map<String,Object>resolveByToken(String token){List<Map<String,Object>>s=jdbc.queryForList("SELECT business_type businessType FROM stall WHERE operation_qr_token=? AND status<>'DISABLED'",token);if(s.isEmpty())throw bad("铺位不存在");String type=Objects.toString(s.get(0).get("businessType"),"");List<Map<String,Object>>r=jdbc.queryForList("SELECT id,name,business_type businessType,version_no versionNo,fields_json fieldsJson FROM operation_clearance_template WHERE enabled=1 AND business_type IN (?, 'DEFAULT') ORDER BY CASE WHEN business_type=? THEN 0 ELSE 1 END,version_no DESC LIMIT 1",type,type);if(r.isEmpty())throw bad("未配置可用的日清模板");Map<String,Object>m=new LinkedHashMap<>(r.get(0));m.put("fields",parse(m.remove("fieldsJson")));return m;}
 @Transactional public Map<String,Object>save(Map<String,Object>b,String user){String name=text(b,"name"),type=text(b,"businessType").toUpperCase(Locale.ROOT);if(name.isBlank())throw bad("模板名称不能为空");if(type.isBlank())type="DEFAULT";Object fields=b.get("fields");List<Map<String,Object>>items=fields instanceof List<?> l?l.stream().filter(Map.class::isInstance).map(x->(Map<String,Object>)x).toList():List.of();if(items.isEmpty())throw bad("至少配置一个检查题");Set<String>codes=new HashSet<>();for(Map<String,Object>f:items){String code=Objects.toString(f.get("code"),"").trim();String label=Objects.toString(f.get("label"),"").trim();String ft=Objects.toString(f.get("type"),"BOOLEAN").toUpperCase(Locale.ROOT);if(!code.matches("[A-Za-z][A-Za-z0-9_]{0,40}")||label.isBlank())throw bad("题目编码或标题不正确");if(!codes.add(code))throw bad("题目编码不能重复");if(!Set.of("BOOLEAN","TEXT","NUMBER","IMAGE").contains(ft))throw bad("不支持的题目类型");f.put("code",code);f.put("label",label);f.put("type",ft);}Integer version=jdbc.queryForObject("SELECT COALESCE(MAX(version_no),0)+1 FROM operation_clearance_template WHERE business_type=?",Integer.class,type);jdbc.update("UPDATE operation_clearance_template SET enabled=0 WHERE business_type=?",type);jdbc.update("INSERT INTO operation_clearance_template(name,business_type,version_no,fields_json,enabled,remark,created_by) VALUES(?,?,?,?,1,?,?)",name,type,version,json(items),text(b,"remark"),user);return jdbc.queryForMap("SELECT id,name,business_type businessType,version_no versionNo,enabled FROM operation_clearance_template WHERE business_type=? AND version_no=?",type,version);}
 @Transactional public void enable(Long id){Map<String,Object>t=one("SELECT business_type businessType FROM operation_clearance_template WHERE id=?",id);jdbc.update("UPDATE operation_clearance_template SET enabled=0 WHERE business_type=?",t.get("businessType"));jdbc.update("UPDATE operation_clearance_template SET enabled=1 WHERE id=?",id);}
 public Evaluation evaluate(String token,Object raw){Map<String,Object>t=resolveByToken(token);Map<String,Object>answers=raw instanceof Map<?,?>m?(Map<String,Object>)m:new LinkedHashMap<>();List<Map<String,Object>>fields=(List<Map<String,Object>>)t.get("fields");boolean normal=true;for(Map<String,Object>f:fields){String code=Objects.toString(f.get("code")),label=Objects.toString(f.get("label"),code),type=Objects.toString(f.get("type"),"BOOLEAN");Object value=answers.get(code);if(Boolean.TRUE.equals(f.get("required"))&&(value==null||value.toString().isBlank()))throw bad("请填写："+label);if("BOOLEAN".equals(type)&&f.containsKey("expected")&&!Objects.equals(Boolean.parseBoolean(Objects.toString(value,"false")),Boolean.parseBoolean(Objects.toString(f.get("expected")))))normal=false;}return new Evaluation(((Number)t.get("id")).longValue(),((Number)t.get("versionNo")).intValue(),Objects.toString(t.get("name")),json(answers),normal,answers);}
 public record Evaluation(Long templateId,Integer version,String name,String answersJson,boolean normal,Map<String,Object>answers){}
 private List<Map<String,Object>>parse(Object v){try{return json.readValue(Objects.toString(v,"[]"),new TypeReference<>(){});}catch(Exception e){throw bad("模板内容无法解析");}}private String json(Object v){try{return json.writeValueAsString(v);}catch(Exception e){throw bad("模板内容无法保存");}}private String text(Map<String,Object>b,String k){return Objects.toString(b.get(k),"").trim();}private Map<String,Object>one(String q,Object...a){List<Map<String,Object>>r=jdbc.queryForList(q,a);if(r.isEmpty())throw bad("模板不存在");return r.get(0);}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}
}
